package com.plagiarismcheckerx.plagx.preflight;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.stream.Stream;
import org.junit.jupiter.api.DynamicTest;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestFactory;

/**
 * src/test/resources/parity/expected.json is generated by the JavaScript reference
 * (plagx-preflight, npm run parity). Every case must match exactly.
 */
class ParityTest {
    private static final Path RESOURCES = Paths.get("src", "test", "resources");

    @SuppressWarnings("unchecked")
    private static Map<String, Object> data() throws IOException {
        String json = new String(Files.readAllBytes(RESOURCES.resolve("parity/expected.json")), StandardCharsets.UTF_8);
        return (Map<String, Object>) Json.parse(json);
    }

    @SuppressWarnings("unchecked")
    private static PlagxPreflight.Options options(Map<String, Object> o) {
        PlagxPreflight.Options opts = new PlagxPreflight.Options();
        if (o.containsKey("minWords")) opts.minWords(((Number) o.get("minWords")).intValue());
        if (o.containsKey("maxWords")) opts.maxWords(((Number) o.get("maxWords")).intValue());
        if (o.containsKey("style")) opts.style((String) o.get("style"));
        if (o.containsKey("checks")) opts.checks(new ArrayList<>((List<String>) (List<?>) o.get("checks")));
        if (o.containsKey("requiredHeadings")) opts.requiredHeadings(new ArrayList<>((List<String>) (List<?>) o.get("requiredHeadings")));
        return opts;
    }

    @TestFactory
    @SuppressWarnings("unchecked")
    Stream<DynamicTest> matchesJavaScript() throws IOException {
        Map<String, Object> data = data();
        Map<String, Object> optionSets = (Map<String, Object>) data.get("optionSets");
        List<Object> cases = (List<Object>) data.get("cases");
        return cases.stream().map(x -> {
            Map<String, Object> c = (Map<String, Object>) x;
            String fixture = (String) c.get("fixture");
            String set = (String) c.get("options");
            return DynamicTest.dynamicTest(fixture + " / " + set, () -> {
                String text = new String(Files.readAllBytes(RESOURCES.resolve("fixtures").resolve(fixture)), StandardCharsets.UTF_8);
                DraftResult result = PlagxPreflight.checkDraft(text, options((Map<String, Object>) optionSets.get(set)));
                assertEquals(Json.stringifyPretty(c.get("result")), Json.stringifyPretty(result.toMap()));
            });
        });
    }

    @Test
    @SuppressWarnings("unchecked")
    void coversEveryFixture() throws IOException {
        Map<String, Object> data = data();
        assertEquals(160, ((List<Object>) data.get("cases")).size());
        assertEquals(PlagxPreflight.VERSION, data.get("version"));
    }
}
